args<-commandArgs(TRUE);A<-normalizePath(args[1],winslash='/');C<-file.path(A,'02_CONTROLLI');rd<-function(n,s){p<-list.files(C,pattern=paste0('^Table_S',n,'_'),full.names=TRUE);read.delim(file.path(p,paste0(s,'.tsv')),check.names=FALSE,quote='"',stringsAsFactors=FALSE)};d<-rd(4,'Kraken_100');K<-as.matrix(d[-1]);rownames(K)<-d[[1]];ann<-rd(3,'Samples_100');rownames(ann)<-ann$sample_name;clr<-function(P){P<-P[,colSums(P)>0,drop=FALSE];P<-P/rowSums(P);L<-log(P+min(P[P>0])/2);L-rowMeans(L)};ss<-function(Z,g){Z<-scale(Z,center=TRUE,scale=FALSE);n<-nrow(Z);gr<-split(1:n,g);B<-sum(vapply(gr,function(ii)length(ii)*sum(colMeans(Z[ii,,drop=FALSE])^2),numeric(1)));T<-sum(Z^2);k<-length(gr);c(R2=B/T,F=(B/(k-1))/((T-B)/(n-k)))}
u<-rd(9,'Unit_map');members<-lapply(u$unit,function(id){if(grepl('^miao_',id)){a<-substr(id,6,6);r<-substr(id,7,7);rownames(K)[grepl(paste0('^',a,'[0-9]+_',r,'_MSO$'),rownames(K))]}else if(grepl('^mut_',id)){rownames(K)[startsWith(rownames(K),paste0(sub('mut_','',id),'_'))]}else rownames(K)[startsWith(rownames(K),id)]});stopifnot(all(lengths(members)==u$n),length(unique(unlist(members)))==100,sum(lengths(members))==100)
meanP<-t(vapply(members,function(m)colMeans(K[m,,drop=FALSE]),numeric(ncol(K))));mature<-t(vapply(seq_along(members),function(i)if(u$representative[i]%in%rownames(K))K[u$representative[i],]else colMeans(K[members[[i]],,drop=FALSE]),numeric(ncol(K))));Zs<-list(clr(mature),clr(meanP));target<-rd(9,'Grouped_units');out<-data.frame()
for(i in 1:nrow(target)){j<-if(grepl('mature',target$collapse[i]))1 else 2;v<-ss(Zs[[j]],u[[target$factor[i]]]);out<-rbind(out,data.frame(test=paste('S9 grouped',target$collapse[i],target$factor[i]),R2_error=abs(v['R2']-target$R2[i]),F_error=abs(v['F']-target$pseudoF[i])))}
cover<-rd(5,'Database_coverage_samples');unclass<-rd(5,'MetaPhlAn_unclassified');hc<-rd(5,'Host_depth_correlations');rownames(cover)<-cover$sample_name;rownames(unclass)<-unclass$sample_name;other<-data.frame()
for(i in 1:nrow(hc)){ids<-cover$sample_name;xx<-as.numeric(ann[ids,hc$x_variable[i]]);yy<-if(hc$y_variable[i]=='unclassified_pct')unclass[ids,'unclassified_pct']else cover[ids,hc$y_variable[i]];use<-is.finite(xx)&is.finite(yy);ct<-cor.test(xx[use],yy[use],method='spearman',exact=FALSE);other<-rbind(other,data.frame(x=hc$x_variable[i],y=hc$y_variable[i],n=sum(use),rho_error=abs(unname(ct$estimate)-hc$rho[i]),p_error=abs(ct$p.value-hc$p_value[i])))}
write.table(out,file.path(C,'S9_GROUPED_UNITS_AUDIT.tsv'),sep='\t',row.names=FALSE);write.table(other,file.path(C,'S5_HOST_CORRELATIONS_AUDIT.tsv'),sep='\t',row.names=FALSE);stopifnot(max(out$R2_error)<1e-9,max(out$F_error)<1e-8,max(other$rho_error)<1e-10,max(other$p_error)<1e-10,all(other$n==98));cat('S9 grouped matrices33 units6 tests PASS; S5 host8 correlations98 samples PASS\n')
